        ItemStack log = new ItemStack((ItemLike)Items.f_41837_);
        ItemStack strippedLog = new ItemStack((ItemLike)Items.f_41845_);
        ItemStack planks = new ItemStack((ItemLike)Items.f_42647_);
        Vec3 itemSpawn = util.vector().centerOf(sawPos.m_7494_().m_122024_());
