        scene.idle(10);
        scene.world().modifyEntity(logItem, e -> e.m_20256_(util.vector().of(0.05, 0.2, 0.0)));
        scene.idle(12);
        scene.world().modifyEntity(logItem, Entity::m_146870_);
        scene.world().createItemOnBeltLike(sawPos, Direction.WEST, log);
        scene.idle(50);
        logItem = scene.world().createItemEntity(util.vector().topOf(sawPos).m_82520_(0.5, -0.1, 0.0), util.vector().of(0.05, 0.18, 0.0), strippedLog);
        scene.idle(12);
