public class PulleyScenes {
    public static void movement(SceneBuilder builder, SceneBuildingUtil util) {
        CreateSceneBuilder scene = new CreateSceneBuilder(builder);
        scene.title("rope_pulley", "Moving Structures using Rope Pulleys");
        scene.configureBasePlate(0, 0, 5);
        scene.scaleSceneView(0.95f);
        scene.setSceneOffsetY(-1.0f);
        Selection reversable = util.select().fromTo(2, 3, 4, 2, 4, 2);
        BlockPos leverPos = util.grid().at(1, 2, 4);
        BlockPos pulleyPos = util.grid().at(2, 4, 2);
        Selection redstoneStuff = util.select().fromTo(leverPos, leverPos.m_122029_());
        scene.world().showSection(util.select().layer(0), Direction.UP);
        ElementLink plank = scene.world().showIndependentSection(util.select().position(2, 1, 2), Direction.UP);
        scene.idle(5);
        scene.world().showSection(util.select().fromTo(1, 4, 3, 2, 1, 4), Direction.DOWN);
        scene.idle(10);
        scene.world().showSection(util.select().position(pulleyPos), Direction.SOUTH);
        scene.idle(20);
        scene.world().toggleRedstonePower(redstoneStuff);
        scene.effects().indicateRedstone(leverPos);
        scene.world().modifyKineticSpeed(reversable, f -> Float.valueOf(-f.floatValue()));
        scene.effects().rotationDirectionIndicator(pulleyPos.m_122019_());
        scene.world().movePulley(pulleyPos, 2.0f, 40);
        scene.idle(45);
        scene.overlay().showText(60).pointAt(util.vector().blockSurface(pulleyPos, Direction.WEST)).attachKeyFrame().text("Rope Pulleys can move blocks vertically when given Rotational Force").placeNearTarget();
        scene.idle(70);
        scene.world().toggleRedstonePower(redstoneStuff);
        scene.effects().indicateRedstone(leverPos);
        scene.world().modifyKineticSpeed(reversable, f -> Float.valueOf(-f.floatValue()));
        scene.effects().rotationDirectionIndicator(pulleyPos.m_122019_());
        scene.world().movePulley(pulleyPos, -2.0f, 40);
        scene.world().moveSection(plank, util.vector().of(0.0, 2.0, 0.0), 40);
        scene.idle(60);
        scene.overlay().showText(60).pointAt(util.vector().blockSurface(pulleyPos, Direction.SOUTH)).text("Direction and Speed of movement depend on the Rotational Input").placeNearTarget();
        scene.world().toggleRedstonePower(redstoneStuff);
        scene.effects().indicateRedstone(leverPos);
        scene.world().modifyKineticSpeed(reversable, f -> Float.valueOf(-f.floatValue()));
        scene.effects().rotationDirectionIndicator(pulleyPos.m_122019_());
        scene.world().movePulley(pulleyPos, 2.0f, 40);
        scene.world().moveSection(plank, util.vector().of(0.0, -2.0, 0.0), 40);
        scene.idle(50);
        scene.world().hideIndependentSection(plank, Direction.NORTH);
        scene.idle(15);
        ElementLink chassis = scene.world().showIndependentSection(util.select().fromTo(2, 1, 1, 0, 2, 1), Direction.SOUTH);
        scene.world().moveSection(chassis, util.vector().of(1.0, 0.0, 1.0), 0);
        scene.world().replaceBlocks(util.select().fromTo(0, 2, 1, 2, 1, 1), Blocks.f_50705_.m_49966_(), false);

