        ElementLink outputElement = scene.world().showIndependentSection(output, Direction.EAST);
        scene.world().moveSection(outputElement, util.vector().of(-2.0, 0.0, 0.0), 0);
        scene.idle(10);
        scene.world().toggleRedstonePower(wire);
        scene.world().toggleRedstonePower(output);
        scene.idle(5);
        scene.overlay().showText(70).pointAt(util.vector().blockSurface(centerLamp, Direction.WEST)).placeNearTarget().text("They will continue to emit redstone power afterwards");
        scene.idle(60);
        scene.world().hideIndependentSection(outputElement, Direction.NORTH);
        scene.world().showSectionAndMerge(util.select().position(centerLamp.m_122024_()), Direction.EAST, rowElement);

